<script setup lang="ts">
import { cloneRecordItems } from '../../shared/record-payload'
type Row=Record<string,any>
type Page='dashboard'|'records'|'reports'
const page=ref<Page>('dashboard'),user=ref<any>(null),auth=ref<'setup'|'login'|'recover'>('login'),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),rows=ref<Row[]>([]),statuses=ref<any[]>([]),dashboard=ref<any>(null)
const modal=ref(false),step=ref(1),editId=ref<number|null>(null),showPassword=ref(false),confirmPassword=ref(''),legacyPrompt=ref(false)
const credentials=reactive({username:'',displayName:'',password:'',recoveryKey:'',newPassword:''})
const password=computed({get:()=>auth.value==='recover'?credentials.newPassword:credentials.password,set:v=>auth.value==='recover'?credentials.newPassword=v:credentials.password=v})
const needsConfirmation=computed(()=>auth.value==='setup'||auth.value==='recover')
const empty=()=>({recordDate:new Date().toISOString().slice(0,10),recordNumber:'',clientName:'',contacts:'',location:'',sourceOfInfo:'',eventDate:'',proformaNo:'',invoiceNo:'',orderFormNo:'',deliveryFormNo:'',statusId:0,taxRateBasisPoints:0,notes:'',items:[{description:'',quantity:1,unitPrice:0}]})
const form=reactive(empty())
const subtotal=computed(()=>form.items.reduce((sum,item)=>sum+Math.round(Number(item.quantity||0)*Number(item.unitPrice||0)),0))
const tax=computed(()=>Math.round(subtotal.value*Number(form.taxRateBasisPoints||0)/10000))
const total=computed(()=>subtotal.value+tax.value)
const money=(n:number)=>`${new Intl.NumberFormat('en-TZ',{maximumFractionDigits:0}).format(Number(n)||0)} TZS`
const date=(value?:string)=>value?new Intl.DateTimeFormat('en-TZ',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${value}T00:00:00`)): '—'
const trendHeight=(count:number)=>{const values=dashboard.value?.last30Days?.map((row:any)=>Number(row.count)||0)||[];return `${Math.max(8,Math.round((count/Math.max(...values,1))*100))}%`}
const fail=(message?:string)=>error.value=message||'Something went wrong. Please try again.'
function changeAuth(next:'setup'|'login'|'recover'){auth.value=next;error.value='';confirmPassword.value='';showPassword.value=false}
async function timed<T>(name:string,operation:Promise<T>):Promise<T>{let timer:ReturnType<typeof setTimeout>|undefined;const timeout=new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(new Error(`${name} is taking longer than 10 seconds.`)),10000)});try{return await Promise.race([operation,timeout])}finally{if(timer)clearTimeout(timer)}}
async function load(){const tasks=[window.api!.statuses.list().then((r:any)=>{if(!r.ok)throw new Error(r.error.message);statuses.value=r.data}),window.api!.records.list({search:search.value}).then((r:any)=>{if(!r.ok)throw new Error(r.error.message);rows.value=r.data}),window.api!.dashboard.data().then((r:any)=>{if(!r.ok)throw new Error(r.error.message);dashboard.value=r.data})];const results=await Promise.allSettled(tasks);const rejected=results.find((item):item is PromiseRejectedResult=>item.status==='rejected');if(rejected)fail(rejected.reason?.message)}
async function checkLegacy(){const r:any=await window.api!.records.legacyStatus();if(r.ok&&r.data.count>0&&!r.data.decided)legacyPrompt.value=true}
async function boot(){const r:any=await window.api?.auth.status();if(!r?.ok)return fail(r?.error?.message);user.value=r.data.user;auth.value=r.data.hasUser?'login':'setup';if(user.value){await load();await checkLegacy()}}
async function signIn(){if(needsConfirmation.value&&password.value!==confirmPassword.value)return fail('Passwords do not match.');busy.value=true;error.value='';try{let r:any;if(auth.value==='setup'){const status:any=await window.api!.auth.status();if(status.data.hasUser){changeAuth('login');notice.value='A workspace already exists. Sign in to continue.';return}r=await timed('Workspace creation',window.api!.auth.setup({username:credentials.username,displayName:credentials.displayName,password:credentials.password}))}else if(auth.value==='login')r=await timed('Sign in',window.api!.auth.login({username:credentials.username,password:credentials.password}));else r=await timed('Password reset',window.api!.auth.recover({username:credentials.username,recoveryKey:credentials.recoveryKey,newPassword:credentials.newPassword}));if(!r.ok)return fail(r.error.message);if(auth.value==='recover'){notice.value=`Password reset. New recovery key: ${r.data.recoveryKey}`;changeAuth('login');return}user.value=auth.value==='setup'?r.data.user:r.data;if(auth.value==='setup')notice.value=`Workspace created. Save this recovery key: ${r.data.recoveryKey}`;await load();await checkLegacy()}catch(reason){fail(reason instanceof Error?reason.message:'Could not complete your request.')}finally{busy.value=false}}
async function logout(){try{await window.api?.auth.logout()}finally{busy.value=false;user.value=null;credentials.password='';credentials.newPassword='';notice.value='';changeAuth('login')}}
async function newRecord(){error.value='';Object.assign(form,empty());const number:any=await window.api!.records.nextNumber();form.recordNumber=number.ok?number.data:'REC-0001';form.statusId=statuses.value.find(s=>s.is_default)?.id||statuses.value[0]?.id||0;editId.value=null;step.value=1;modal.value=true}
async function edit(row:Row){const r:any=await window.api!.records.get(row.id);if(!r.ok||!r.data)return fail(r.error?.message);const x=r.data.record;Object.assign(form,{recordDate:x.record_date,recordNumber:x.record_number||'',clientName:x.client_name,contacts:x.contacts||'',location:x.location||'',sourceOfInfo:x.source_of_info||'',proformaNo:x.proforma_no||'',invoiceNo:x.invoice_no||'',eventDate:x.event_date||'',orderFormNo:x.order_form_no||'',deliveryFormNo:x.delivery_form_no||'',statusId:x.status_id,taxRateBasisPoints:x.tax_rate_bp,notes:x.notes||'',items:r.data.items.map((i:any)=>({description:i.description,quantity:i.quantity_x100/100,unitPrice:i.unit_price_minor}))});editId.value=row.id;step.value=1;modal.value=true}
function validStep(){if(step.value===1&&!form.clientName.trim()){fail('Enter a client name to continue.');return false}if(step.value===2&&form.items.some(item=>!item.description.trim()||Number(item.quantity)<=0||Number(item.unitPrice)<0)){fail('Each item needs a name, a quantity, and a price.');return false}error.value='';return true}
function next(){if(validStep())step.value=Math.min(4,step.value+1)}
async function save(){if(!validStep())return;busy.value=true;error.value='';const record={recordDate:form.recordDate,recordNumber:form.recordNumber,clientName:form.clientName,contacts:form.contacts,location:form.location,sourceOfInfo:form.sourceOfInfo,eventDate:form.eventDate,proformaNo:form.proformaNo,invoiceNo:form.invoiceNo,orderFormNo:form.orderFormNo,deliveryFormNo:form.deliveryFormNo,statusId:Number(form.statusId),currency:'TZS',taxRateBasisPoints:Number(form.taxRateBasisPoints),notes:form.notes};const items=cloneRecordItems(form.items);try{const r:any=editId.value===null?await window.api!.records.create({record,items}):await window.api!.records.update({id:editId.value,record,items});if(!r.ok)return fail(r.error.message);modal.value=false;notice.value='Record saved.';await load()}catch(reason){fail(reason instanceof Error?reason.message:'Could not save this record. Please try again.')}finally{busy.value=false}}
async function freshStart(){busy.value=true;const r:any=await window.api!.records.clearLegacy();busy.value=false;if(!r.ok)return fail(r.error.message);legacyPrompt.value=false;notice.value='Test records were cleared. You can start with the corrected TZS model.';await load()}
async function keepLegacy(){await window.api!.records.keepLegacy();legacyPrompt.value=false}
const reportType=ref<'daily'|'monthly'|'upcoming-events'>('monthly'),report=ref<any>(null),reportDay=ref(new Date().toISOString().slice(0,10)),reportMonth=ref(new Date().toISOString().slice(0,7)),reportDays=ref(7)
async function previewReport(){const params=reportType.value==='daily'?{day:reportDay.value}:reportType.value==='monthly'?{month:reportMonth.value}:{days:reportDays.value};const r:any=await window.api!.reports!.data(reportType.value,params);if(!r.ok)return fail(r.error.message);report.value=r.data}
async function exportExcel(){if(!report.value)return;const r:any=await window.api!.reports!.exportExcel(report.value);if(!r.ok)return fail(r.error.message);if(r.data)notice.value='Excel report saved.'}
async function exportPdf(){if(!report.value)return;const r:any=await window.api!.reports!.exportPdf(`Business-Records_${report.value.period}`);if(!r.ok)return fail(r.error.message);if(r.data)notice.value='PDF report saved.'}
function openReports(){page.value='reports';if(!report.value)void previewReport()}
onMounted(boot)
</script>
<template>
<main v-if="user" class="app"><aside><div class="brand"><b>BR</b><span>BUSINESS<br><strong>RECORDS</strong></span></div><nav><button :class="{active:page==='dashboard'}" @click="page='dashboard'">Overview</button><button :class="{active:page==='records'}" @click="page='records'">Records</button><button :class="{active:page==='reports'}" @click="openReports">Reports</button></nav><button class="logout" @click="logout">Sign out</button></aside><section class="content"><header><div><p>{{page==='dashboard'?'EXECUTIVE OVERVIEW':page==='reports'?'REPORTING':'RECORD MANAGEMENT'}}</p><h1>{{page==='dashboard'?`Good day, ${user.displayName.split(' ')[0]}`:page==='reports'?'Reports':'Business records'}}</h1></div><button v-if="page!=='reports'" class="primary" @click="newRecord">+ New record</button></header><div v-if="notice" class="notice">{{notice}} <button @click="notice=''">×</button></div><p v-if="error&&!modal" class="error">{{error}}</p>
<template v-if="page==='dashboard'"><section class="metrics"><article><span>MONTHLY VALUE</span><strong>{{money(dashboard?.monthSummary?.[0]?.total)}}</strong><small>Non-cancelled records this month</small></article><article><span>RECORDS TODAY</span><strong>{{dashboard?.recordsToday||0}}</strong><small>Created today</small></article><article><span>ACTIVE RECORDS</span><strong>{{dashboard?.activeRecords||0}}</strong><small>Current business records</small></article><article><span>UPCOMING EVENTS</span><strong>{{dashboard?.upcomingEvents?.length||0}}</strong><small>Next seven days</small></article></section><section class="dashboard-grid"><article class="card"><div class="heading"><div><h2>Activity over the last 30 days</h2><small>Records created each day</small></div></div><div v-if="dashboard?.last30Days?.length" class="trend"><i v-for="d in dashboard.last30Days" :key="d.record_date" :style="{height:trendHeight(d.count)}" :title="`${d.record_date}: ${d.count} records`"></i></div><div v-else class="trend empty">No activity yet</div></article><article class="card"><h2>Record status</h2><div class="status" v-for="s in dashboard?.byStatus||[]" :key="s.name"><span><i :style="{background:s.color}"></i>{{s.name}}</span><b>{{s.count}}</b></div></article><article class="card full"><div class="heading"><div><h2>Recent records</h2><small>Your latest business activity</small></div><button @click="page='records'">View all</button></div><div v-if="rows.length" class="list"><button v-for="r in rows.slice(0,6)" :key="r.id" @click="edit(r)"><i>{{r.client_name.slice(0,1)}}</i><span><strong>{{r.client_name}}</strong><small>{{r.record_number||'No reference'}} · {{date(r.record_date)}}</small></span><strong>{{money(r.grand_total_minor)}}</strong><em :style="{'--c':r.status_color}">{{r.status_name}}</em></button></div><div v-else class="empty"><strong>No records yet</strong><p>Create your first record to see activity here.</p></div></article></section></template>
<template v-else-if="page==='records'"><div class="toolbar"><input v-model="search" placeholder="Search client, record or invoice" @input="load"><span>{{rows.length}} records</span></div><article class="card table"><table><thead><tr><th>RECORD</th><th>CLIENT</th><th>DATE</th><th>STATUS</th><th>TOTAL</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.record_number||'—'}}</td><td><strong>{{r.client_name}}</strong><small>{{r.contacts||'No contact details'}}</small></td><td>{{date(r.record_date)}}</td><td><em :style="{'--c':r.status_color}">{{r.status_name}}</em></td><td><strong>{{money(r.grand_total_minor)}}</strong></td><td><button @click="edit(r)">Edit</button></td></tr></tbody></table><div v-if="!rows.length" class="empty">No matching records.</div></article></template>
<template v-else><article class="card report-controls"><label>Report type<select v-model="reportType"><option value="daily">Daily report</option><option value="monthly">Monthly report</option><option value="upcoming-events">Upcoming events</option></select></label><label v-if="reportType==='daily'">Date<input v-model="reportDay" type="date"></label><label v-if="reportType==='monthly'">Month<input v-model="reportMonth" type="month"></label><label v-if="reportType==='upcoming-events'">Days ahead<input v-model.number="reportDays" type="number" min="1" max="365"></label><button class="primary" @click="previewReport">Preview report</button></article><article v-if="report" class="card report-preview"><div class="heading"><div><p>PREVIEW</p><h2>{{report.type.replaceAll('-',' ')}}</h2><small>{{report.period}}</small></div><div><button @click="exportExcel">Export Excel</button><button class="primary" @click="exportPdf">Save PDF</button></div></div><section v-if="report.summary?.length" class="report-summary"><div v-for="s in report.summary" :key="JSON.stringify(s)"><small>{{s.records||'Total'}} records</small><strong>{{money(s.total_minor)}}</strong></div></section><div class="table"><table><thead><tr><th>RECORD</th><th>CLIENT</th><th>DATE</th><th>STATUS</th><th>TOTAL</th></tr></thead><tbody><tr v-for="r in report.rows" :key="r.id"><td>{{r.record_number||'—'}}</td><td>{{r.client_name}}</td><td>{{date(r.record_date||r.event_date)}}</td><td>{{r.status_name}}</td><td>{{money(r.grand_total_minor)}}</td></tr></tbody></table><div v-if="!report.rows.length" class="empty">No records for this report.</div></div></article></template></section></main>
<main v-else class="auth"><section class="intro"><div class="brand"><b>BR</b><span>BUSINESS<br><strong>RECORDS</strong></span></div><div><p>OFFLINE BUSINESS MANAGEMENT</p><h1>Your business,<br>organized.</h1><span>Securely manage records, invoices, events, and client activity from one private desktop workspace.</span></div><small>Local data · Private by design</small></section><form @submit.prevent="signIn"><p>{{auth==='setup'?'WELCOME':auth==='recover'?'ACCOUNT RECOVERY':'WELCOME BACK'}}</p><h2>{{auth==='setup'?'Create your workspace':auth==='recover'?'Reset your password':'Sign in to continue'}}</h2><label v-if="auth==='setup'">Your name<input v-model="credentials.displayName" required></label><label>Username<input v-model="credentials.username" required></label><label v-if="auth==='recover'">Recovery key<input v-model="credentials.recoveryKey" required></label><label>{{auth==='recover'?'New password':'Password'}}<span class="password"><input v-model="password" :type="showPassword?'text':'password'" minlength="6" required><button type="button" @click="showPassword=!showPassword">{{showPassword?'Hide':'Show'}}</button></span></label><label v-if="needsConfirmation">Confirm password<input v-model="confirmPassword" :type="showPassword?'text':'password'" minlength="6" required></label><p v-if="needsConfirmation&&confirmPassword&&password!==confirmPassword" class="error">Passwords do not match.</p><p v-else-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?'Please wait…':auth==='setup'?'Create workspace':auth==='recover'?'Reset password':'Sign in'}}</button><button v-if="auth!=='login'" type="button" @click="changeAuth('login')">Back to sign in</button><button v-if="auth==='login'" type="button" @click="changeAuth('recover')">Forgot password?</button></form></main>
<div v-if="legacyPrompt" class="shade"><section class="dialog"><p>CALCULATION UPDATE</p><h2>Start with corrected TZS records?</h2><span>The previous test records used an incorrect amount model. Starting fresh deletes records and their items, but keeps your account and settings.</span><footer><button @click="keepLegacy">Keep existing records</button><button class="danger" :disabled="busy" @click="freshStart">Start fresh</button></footer></section></div>
<div v-if="modal" class="shade" @mousedown.self="modal=false"><section class="modal"><header><div><p>{{editId===null?'NEW RECORD':'EDIT RECORD'}} · STEP {{step}} OF 4</p><h2>{{['Record details','Items and totals','Documents and remarks','Review and save'][step-1]}}</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="step===4?save():next()"><div class="body"><p v-if="error" class="error">{{error}}</p><fieldset v-if="step===1"><div class="fields"><label>Record date *<input v-model="form.recordDate" type="date" required></label><label>Record number<input v-model="form.recordNumber" readonly></label><label>Client *<input v-model="form.clientName" required></label><label>Contacts<input v-model="form.contacts"></label><label>Location<input v-model="form.location"></label><label>Source of information<input v-model="form.sourceOfInfo"></label></div></fieldset><fieldset v-if="step===2"><div class="item head"><span>ITEM</span><span>QUANTITY</span><span>PRICE (TZS)</span><span>AMOUNT</span></div><div v-for="(item,index) in form.items" :key="index" class="item"><input v-model="item.description" placeholder="Item or service" required><input v-model.number="item.quantity" type="number" min="1" step="1"><input v-model.number="item.unitPrice" type="number" min="0" step="1"><strong>{{money(item.quantity*item.unitPrice)}}</strong><button type="button" :disabled="form.items.length===1" @click="form.items.splice(index,1)">×</button></div><button type="button" class="add" @click="form.items.push({description:'',quantity:1,unitPrice:0})">+ Add item</button><div class="totals"><label>Tax (%)<input :value="form.taxRateBasisPoints/100" type="number" min="0" @input="form.taxRateBasisPoints=Number(($event.target as HTMLInputElement).value)*100"></label><div><small>Subtotal</small><b>{{money(subtotal)}}</b></div><div><small>Total</small><b>{{money(total)}}</b></div></div></fieldset><fieldset v-if="step===3"><div class="fields"><label>Event date<input v-model="form.eventDate" type="date"></label><label>Proforma invoice number<input v-model="form.proformaNo"></label><label>Invoice number<input v-model="form.invoiceNo"></label><label>Order form number<input v-model="form.orderFormNo"></label><label>Delivery form number<input v-model="form.deliveryFormNo"></label><label>Status<select v-model.number="form.statusId"><option v-for="s in statuses" :key="s.id" :value="s.id">{{s.name}}</option></select></label></div><label class="notes">Remarks (notes)<textarea v-model="form.notes" rows="4"></textarea></label></fieldset><fieldset v-if="step===4" class="review"><div><small>RECORD</small><strong>{{form.recordNumber}} · {{date(form.recordDate)}}</strong></div><div><small>CLIENT</small><strong>{{form.clientName}}</strong></div><div><small>TOTAL</small><strong>{{money(total)}}</strong></div><div v-for="item in form.items" :key="item.description" class="review-item"><span>{{item.description}} × {{item.quantity}}</span><b>{{money(item.quantity*item.unitPrice)}}</b></div></fieldset></div><footer><button v-if="step>1" type="button" @click="step--">Back</button><button type="button" @click="modal=false">Cancel</button><button class="primary" :disabled="busy">{{step===4?(busy?'Saving…':'Save record'):'Continue'}}</button></footer></form></section></div>
</template>
<style scoped>
